let colors = ['#f9c80e', '#f86624', '#ea3546', '#662e9b', '#32a852', '#43bccd'];
let ctx;
let boxes = [];

function setup() {
	createCanvas(900, 900, WEBGL);
	rectMode(CENTER);
	ctx = drawingContext;
	INIT();
}

function draw() {
  // === Variant 4: Dynamic Feedback Trail ===
  // Lower background clear to force deep visual echoing

	background(10, 10, 15, 6);
	for (let b of boxes) {
		b.run();
	}

	if (frameCount % 130 == 0) {
		INIT();
	}
}

function INIT() {
	boxes = [];
	let side = 400;
	divideBox(0, 0, 0, side, side, side, 10);
}

function divideBox(x, y, z, w, h, d, n) {
	n--;
	if (n > 0) {
		if (w >= h && w >= d) {
			let ww = random(0.25, 0.75) * w;
			let www = w - ww;
			divideBox(x - (w / 2) + (ww / 2), y, z, ww, h, d, n);
			divideBox(x + (w / 2) - (www / 2), y, z, www, h, d, n);
		} else if (h > w && h > d) {
			let hh = random(0.25, 0.75) * h;
			let hhh = h - hh;
			divideBox(x, y - (h / 2) + (hh / 2), z, w, hh, d, n);
			divideBox(x, y + (h / 2) - (hhh / 2), z, w, hhh, d, n);
		} else {
			let dd = random(0.25, 0.75) * d;

			let ddd = d - dd;
			divideBox(x, y, z - (d / 2) + (dd / 2), w, h, dd, n);
			divideBox(x, y, z + (d / 2) - (ddd / 2), w, h, ddd, n);
		}
	} else {
		boxes.push(new Box(x, y, z, w, h, d));
	}
}

function easeInOutQuart(x) {
	return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
}


class Box {
	constructor(x, y, z, w, h, d) {
		this.x = x;
		this.y = y;
		this.z = z;
		this.w = w;
		this.h = h;
		this.d = d;
		this.dst = dist(0, 0, 0, x, y, z);
		let r = this.dst * 0.5;
		this.theta = atan2(y - 0, x - 0);
		this.t = -int((300 - this.dst) * 0.02);
		this.t1 = 50;
		this.t2 = 40 + this.t1;
		this.t3 = 50 + this.t2;

		this.x0 = x;
		this.x1 = x + (r * (x / this.dst));
		this.y0 = y;
		this.y1 = y + (r * (y / this.dst));
		this.z0 = z;
		this.z1 = z + (r * (z / this.dst));
		this.f = 0;
		this.clr = random(colors);
	}

	show() {
		push();
		noStroke();
		fill(this.clr);
		translate(this.x, this.y, this.z);
		box(this.w, this.h, this.d - 1);
		fill(0);
		beginShape();
		vertex(-this.w / 2, -this.h / 2, this.d / 2);
		vertex(this.w / 2, -this.h / 2, this.d / 2);
		vertex(this.w / 2, this.h / 2, this.d / 2);
		vertex(-this.w / 2, this.h / 2, this.d / 2);
		endShape(CLOSE);
		pop();
	}

	move() {
		this.t++;
		if (0 < this.t && this.t < this.t1) {
			let n = norm(this.t, 0, this.t1 - 1);
			this.x = lerp(this.x0, this.x1, easeInOutQuart(n));
			this.y = lerp(this.y0, this.y1, easeInOutQuart(n));
			this.z = lerp(this.z0, this.z1, easeInOutQuart(n));
		}
		else if (this.t2 < this.t && this.t < this.t3) {
			let n = norm(this.t, this.t2, this.t3 - 1);
			this.x = lerp(this.x1, this.x0, easeInOutQuart(n));
			this.y = lerp(this.y1, this.y0, easeInOutQuart(n));
			this.z = lerp(this.z1, this.z0, easeInOutQuart(n));
		}
	}

	run() {
		this.show();
		this.move();
	}
}

